from taf.sbts.oam.coam.admin.interface import admin

from taf.rfrl.procedures.resources.python.logger import log_input_and_output


@log_input_and_output
def get_active_tests(connection, timeout=60):
    """
    Gets list of active conformance tests.
    :param connection: AdminConnection object or if used, string name alias
    :type connection: AdminConnection or str
    :param timeout: timeout for api request
    :type timeout: int
    :return: List of active conformance tests
    :rtype: list
    """
    adm = admin()
    return adm.get_active_tests(connection=connection, timeout=timeout)
